   310→                  provider: 'google',
   311→                  options: {
   312→                        redirectTo: `${window.location.origin}/auth/callback`,
   313→                  },
   314→            });
   315→            if (error) throw error;
   316→      };
   317→
   318→      // ─── refreshProfile ──────────────────────────
   319→
