import './globals.css';
import type { Metadata, Viewport } from 'next';
import Toast from '@/components/Toast';
import ErrorBoundary from '@/components/ErrorBoundary';
import ErrorFallback from '@/components/ErrorFallback';
import Footer from "@/components/Footer";
import { AuthProvider } from "@/context/AuthContext";
import { BookmarksProvider } from '@/context/BookmarkContext';
import Header from '@/components/NavBar';

export const metadata: Metadata = {
  title: 'Bookmark Vault',
  description: 'come get Organize your Bookmarks.',
  icons: {
    icon: '/icon.svg',
  },
};

export const viewport: Viewport = {
  width: 'device-width',
  initialScale: 1,
  viewportFit: 'cover',
  themeColor: '#000000',
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <body className="bg-black text-[#e4e2e4] antialiased min-h-screen flex flex-col">
        <ErrorBoundary FallbackComponent={ErrorFallback}>
          <div className="flex-1 flex flex-col min-h-0">
            <AuthProvider>
              <BookmarksProvider>
                <Header />
                <main className="flex-1 pt-20 md:pt-28">
                  {children}
                </main>
              </BookmarksProvider>
            </AuthProvider>
          </div>
        </ErrorBoundary>
        <Toast />
        <Footer />
      </body>
    </html>
  );
}

'use client';

import { Suspense } from 'react';
import Link from 'next/link';
import { useSearchParams } from 'next/navigation';

function AuthErrorContent() {
      const searchParams = useSearchParams();
      const reason =
            searchParams.get('reason') ?? 'Something went wrong during sign-in.';

      return (
            <div className="min-h-[60vh] flex items-center justify-center px-4" >
                  <div className="max-w-md w-full text-center space-y-5 p-8 rounded-2xl bg-white/[0.03] border border-white/10" >
                        <h1 className="text-white text-2xl font-bold tracking-tight" >
                              Sign -in failed
                        </h1>
                        < p className="text-white/60 text-sm leading-relaxed" > {reason} </p>
                        < div className="flex gap-3 justify-center pt-2" >
                              <Link
                                    href="/"
                                    className="px-5 py-2.5 rounded-xl bg-white/[0.05] hover:bg-white/[0.1] text-white text-sm font-semibold transition - colors"
                              >
                                    Back to sign in
                              </Link>
                        </div>
                  </div>
            </div>
      );
}

export default function AuthErrorPage() {
      return (
            <Suspense fallback={< div className="min-h-[60vh]" />}>
                  <AuthErrorContent />
            </Suspense>
      );
}

