    60→
    61→/** Extracts a display name from Supabase auth user metadata. */
    62→function extractDisplayName(user: User | null): string | null {
    63→      const meta = user?.user_metadata as Record<string, unknown> | undefined;
    64→      for (const key of ["name", "full_name", "first_name"]) {
    65→            const val = meta?.[key];
    66→            if (typeof val === "string" && val.trim()) return val.trim();
