    99→       */
   100→      const fetchProfile = useCallback(
   101→            async (userId: string, authUser: User | null
   102→                  // , email: string
   103→            ) => {
   104→                  // Guard against concurrent calls (e.g. rapid auth state changes)
   105→                  if (isFetchingProfile.current) return;
